              .some((entry) => entry.type === "message" && entry.message?.role === message.role);
          if (result.sessionId !== sessionId || persistedMessages.has(message) || replaced) pending.delete(message);
        }
        cachedManager = manager;
        cachedSession = sessionId;
        cachedLeaf = leafId;
      }
